{
  "avaliacoes": [
    {
      "id": "E11483a0c65448a26",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Os sistemas permanentes de amarração são apresentados como meios para garantir a estabilidade de estruturas flutuantes offshore, incluindo SPM, spread mooring e posicionamento dinâmico.",
          "trechos": [
            "E11483a0c65448a26:0:695",
            "E11483a0c65448a26:695:1384"
          ],
          "condicoes": [
            "Aplicável a estruturas flutuantes em ambiente offshore."
          ],
          "limites": [
            "O trecho é descritivo e não trata de hook-up, pré-tensão, retensionamento ou condição avariada."
          ]
        },
        {
          "proposicao": "No spread mooring, as linhas são distribuídas ao redor do FPSO ou FSO para resistir aos carregamentos ambientais atuantes.",
          "trechos": [
            "E11483a0c65448a26:695:1384"
          ],
          "condicoes": [
            "Associado ao uso de spread mooring."
          ],
          "limites": [
            "O trecho afirma uso em ambientes menos agressivos, sem definir critérios quantitativos.",
            "Não explicita como ocorre a distribuição de cargas entre linhas."
          ]
        },
        {
          "proposicao": "A seleção da configuração de linha de ancoragem é relacionada a tipo de plataforma, lâmina d’água, número de risers, intensidade das cargas e custo dos materiais; na catenária convencional há trecho apoiado no leito e transmissão apenas de esforços horizontais à fundação.",
          "trechos": [
            "E11483a0c65448a26:1384:2084",
            "E11483a0c65448a26:2084:2396"
          ],
          "condicoes": [
            "Para configuração convencional do tipo catenária."
          ],
          "limites": [
            "Não aborda instalação, ajuste de pré-tensão, redistribuição após falha ou comportamento avariado."
          ]
        }
      ]
    },
    {
      "id": "E7276e1bbb61a86d6",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A função geral de uma estrutura oceânica de produção inclui suportar planta de processo, equipamentos e risers, o que contextualiza a interação entre unidade flutuante e sistema de amarração.",
          "trechos": [
            "E7276e1bbb61a86d6:692:1389",
            "E7276e1bbb61a86d6:1389:2087"
          ],
          "condicoes": [
            "No contexto de estruturas flutuantes de exploração e produção."
          ],
          "limites": [
            "Não detalha distribuição de cargas nem comportamento intacto ou avariado."
          ]
        },
        {
          "proposicao": "No sistema SMS/Spread Mooring System, o FPSO usa várias linhas de ancoragem, podendo ser em catenária simples ou com flutuadores intermediários ou pesos, ancoradas ao fundo por âncoras de arrasto ou estacas.",
          "trechos": [
            "E7276e1bbb61a86d6:1389:2087"
          ],
          "condicoes": [
            "Para FPSOs classificados segundo sistema de posicionamento."
          ],
          "limites": [
            "O trecho não informa critérios de seleção entre as variantes nem consequências operacionais dessas escolhas."
          ]
        },
        {
          "proposicao": "No spread mooring, a outra extremidade das linhas é ligada ao perímetro do navio, mantendo o aproamento praticamente fixo.",
          "trechos": [
            "E7276e1bbb61a86d6:1389:2087",
            "E7276e1bbb61a86d6:2087:2211"
          ],
          "condicoes": [
            "Aplicável ao arranjo spread mooring descrito."
          ],
          "limites": [
            "O texto diz 'praticamente fixo', indicando aproximação e não ausência total de variação de aproamento.",
            "Não cobre retensionamento, redistribuição de carga por linha ou falha de linha."
          ]
        }
      ]
    },
    {
      "id": "E256ac88faae72067",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A função do sistema de ancoragem é restringir deslocamentos de carregamento ambiental para manter a unidade dentro de uma região segura de operação; sua eficiência pode ser avaliada pelo passeio sob condição de tempo mais severa.",
          "trechos": [
            "E256ac88faae72067:0:698",
            "E256ac88faae72067:698:1398"
          ],
          "condicoes": [
            "Para unidades flutuantes submetidas a carregamentos ambientais."
          ],
          "limites": [
            "Não apresenta limites numéricos de excursão.",
            "Não trata de critérios específicos de FPSO em hook-up ou pós-avaria."
          ]
        },
        {
          "proposicao": "Maior rigidez tende a reduzir o passeio, mas o material das linhas impõe limite superior à rigidez porque o aumento da rigidez eleva as trações e as tensões internas nas linhas.",
          "trechos": [
            "E256ac88faae72067:698:1398"
          ],
          "condicoes": [
            "Relação válida no contexto da resposta do sistema de ancoragem e do material empregado nas linhas."
          ],
          "limites": [
            "É uma explicação qualitativa; não fornece valores de rigidez, tração ou critérios de aceitação."
          ]
        },
        {
          "proposicao": "A composição do sistema deve garantir integridade durante a operação e evitar falha por fadiga; a escolha do tipo de ancoragem depende da geometria das linhas, tipo de embarcação, operação, quantidade de risers, custo e profundidade do mar.",
          "trechos": [
            "E256ac88faae72067:698:1398",
            "E256ac88faae72067:1398:2098",
            "E256ac88faae72067:2098:2167"
          ],
          "condicoes": [
            "No projeto e seleção de sistemas de ancoragem offshore."
          ],
          "limites": [
            "Não descreve procedimentos de inspeção, retensionamento ou resposta após falha de linha."
          ]
        }
      ]
    },
    {
      "id": "E3132ede1edc4dcf7",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "São descritos três grupos principais de sistemas de amarração para estruturas flutuantes: SPM, spread mooring e posicionamento dinâmico, com possibilidade de o DP atuar em conjunto com outros sistemas.",
          "trechos": [
            "E3132ede1edc4dcf7:0:699",
            "E3132ede1edc4dcf7:699:1398"
          ],
          "condicoes": [
            "Para estruturas flutuantes offshore."
          ],
          "limites": [
            "Não há detalhamento de hook-up, pré-tensão ou falha."
          ]
        },
        {
          "proposicao": "O spread mooring é indicado no texto para ambientes menos agressivos e distribui linhas em torno do FPSO ou FSO para resistir aos carregamentos ambientais.",
          "trechos": [
            "E3132ede1edc4dcf7:699:1398"
          ],
          "condicoes": [
            "Segundo a caracterização apresentada nessa fonte."
          ],
          "limites": [
            "A expressão 'menos agressivos' não é quantificada.",
            "Não há critério operacional brasileiro formalizado no trecho."
          ]
        },
        {
          "proposicao": "A configuração convencional catenária é descrita como tendo trecho da linha apoiado no leito marinho, transmitindo apenas esforços horizontais à fundação, com comprimento aproximado de duas a três vezes a lâmina d’água.",
          "trechos": [
            "E3132ede1edc4dcf7:1398:2088",
            "E3132ede1edc4dcf7:2088:2382"
          ],
          "condicoes": [
            "Para linhas de ancoragem em configuração convencional."
          ],
          "limites": [
            "O trecho não trata de distribuição de carga entre várias linhas, pré-tensionamento nem condição avariada."
          ]
        }
      ]
    },
    {
      "id": "Edd15917fdaa1e156",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A análise estática de ancoragem mencionada requer dados de geometria, propriedades das linhas, condições de contorno e características ambientais e da plataforma.",
          "trechos": [
            "Edd15917fdaa1e156:0:700",
            "Edd15917fdaa1e156:700:1399"
          ],
          "condicoes": [
            "No uso do arquivo de dados de ancoragem para análise estática."
          ],
          "limites": [
            "Trata de requisitos de entrada de cálculo, não de procedimento de instalação em campo."
          ]
        },
        {
          "proposicao": "A pré-tensão da linha de amarração aparece explicitamente como condição de contorno na análise, indicando sua relevância para o comportamento calculado do sistema.",
          "trechos": [
            "Edd15917fdaa1e156:0:700"
          ],
          "condicoes": [
            "No contexto do arquivo de dados usado pelo programa DMOOR."
          ],
          "limites": [
            "A fonte não informa como a pré-tensão é definida, medida, aplicada ou reajustada em hook-up ou retensionamento."
          ]
        },
        {
          "proposicao": "No caso descrito, o programa DMOOR considera ações ambientais colineares conforme metodologia da API, e um programa adicional foi usado para considerar corretamente direções distintas dos carregamentos ambientais nos deslocamentos estáticos.",
          "trechos": [
            "Edd15917fdaa1e156:700:1399",
            "Edd15917fdaa1e156:1399:2099",
            "Edd15917fdaa1e156:2099:2272"
          ],
          "condicoes": [
            "Para análise dos deslocamentos estáticos da plataforma P-X nos programas citados."
          ],
          "limites": [
            "Refere-se a um caso e a ferramentas específicas.",
            "Não demonstra comportamento avariado nem redistribuição de cargas após falha de linha."
          ]
        }
      ]
    },
    {
      "id": "E660c5a902b7067d5",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No FPSO com ancoragem em ponto único por turret, as linhas convergem para um mesmo ponto e a estrutura permite o giro do navio em torno do sistema de ancoragem e dos risers, que permanecem estacionários em relação ao fundo.",
          "trechos": [
            "E660c5a902b7067d5:0:700"
          ],
          "condicoes": [
            "Para FPSOs com turret localizado geralmente na proa, conforme descrito."
          ],
          "limites": [
            "O trecho é descritivo e não cobre critérios de integridade ou pós-avaria."
          ]
        },
        {
          "proposicao": "No spread mooring, os risers são geralmente conectados a um dos bordos, deixando o outro livre para operações de transferência de cargas.",
          "trechos": [
            "E660c5a902b7067d5:700:1399"
          ],
          "condicoes": [
            "No arranjo de FPSO com ancoragem distribuída."
          ],
          "limites": [
            "O uso de 'geralmente' indica prática comum, não regra universal.",
            "Não detalha impactos sobre distribuição de cargas nas linhas."
          ]
        },
        {
          "proposicao": "No arranjo DICAS, as linhas de popa são menos tensionadas que as de proa, permitindo alguma liberdade de alinhamento com as condições ambientais.",
          "trechos": [
            "E660c5a902b7067d5:700:1399"
          ],
          "condicoes": [
            "Para o caso particular de spread mooring do tipo DICAS."
          ],
          "limites": [
            "O valor angular citado no trecho está apagado e não pode ser reconstruído.",
            "A fonte não informa método de ajuste dessas tensões nem comportamento após falha de linha."
          ]
        }
      ]
    }
